import math
    import random
    import time

    LANGUAGE_WRAPPER = 'A transformation of the first quadrant of the coordinate plane maps each point (x, y) to (sqrt(x), sqrt(y)). Consider the region R bounded by the rays y = {r1_num}/{r1_den} · x and y = {r2_num}/{r2_den} · x, and by the two lines {a}x + {b}y = {c1} and {a}x + {b}y = {c2}, where all constants are positive and {c2} > {c1}. Let k be the area of the image of R under this transformation. Find the greatest integer that does not exceed k.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# The region is bounded by y = r1 x, y = r2 x (0<r1<r2) and ax+by=c1, ax+by=c2 (c2>c1>0)
# Under (x,y) -> (sqrt(x), sqrt(y)), ax+by=c becomes a u^2 + b v^2 = c (ellipses),
# and y = r x becomes v = sqrt(r) u (rays). A linear scaling (w,z)=(sqrt(a)u, sqrt(b)v)
# turns ellipses into circles w^2+z^2=c with area scale sqrt(a b). The image area is
# (1/sqrt(a b)) times the annular circular sector area: 0.5 * (c2-c1) * (Delta theta).
tries = 0
while True:
    tries += 1
    a = rng.randint(1, 9)
    b = rng.randint(1, 9)
    base = rng.randint(500, 3200)
    diff = rng.choice([200, 300, 400, 500, 600, 800, 900, 1000, 1200, 1500])
    c1 = base
    c2 = base + diff
    p1 = rng.randint(1, 9)
    q1 = rng.randint(2, 9)
    p2 = rng.randint(1, 12)
    q2 = rng.randint(2, 12)
    r1 = p1 / q1
    r2 = p2 / q2
    if r1 >= r2:
        # Randomly swap or retry to ensure r1<r2
        if rng.random() < 0.5:
            continue
        r1, r2 = r2, r1
        p1, q1, p2, q2 = p2, q2, p1, q1
    S = math.sqrt(b / a)
    t1 = S * math.sqrt(r1)
    t2 = S * math.sqrt(r2)
    dtheta = abs(math.atan(t2) - math.atan(t1))
    area = 0.5 * (c2 - c1) * dtheta / math.sqrt(a * b)
    specials = [0.0, 1.0, math.sqrt(3), 1.0 / math.sqrt(3)]
    near_special = any(abs(t1 - s) < 1e-9 or abs(t2 - s) < 1e-9 for s in specials)
    if dtheta < 0.2 or dtheta > 1.2:
        continue
    if area < 100 or area > 2000:
        continue
    if near_special:
        continue
    if c1 <= 0 or c2 <= c1:
        continue
    return {
        'a': a,
        'b': b,
        'c1': c1,
        'c2': c2,
        'r1_num': p1,
        'r1_den': q1,
        'r2_num': p2,
        'r2_den': q2
    }

    def verifier(assign):
import math
# Validate keys
try:
    a = assign['a']
    b = assign['b']
    c1 = assign['c1']
    c2 = assign['c2']
    p1 = assign['r1_num']
    q1 = assign['r1_den']
    p2 = assign['r2_num']
    q2 = assign['r2_den']
except Exception:
    # Missing slots
    return (False, None)
# Type and domain checks
if not all(isinstance(x, int) for x in [a, b, c1, c2, p1, q1, p2, q2]):
    return (False, None)
if a <= 0 or b <= 0 or c1 <= 0 or c2 <= c1 or p1 <= 0 or q1 <= 0 or p2 <= 0 or q2 <= 0:
    return (False, None)
r1 = p1 / q1
r2 = p2 / q2
if not (r1 > 0 and r2 > 0 and r1 < r2):
    return (False, None)
# Compute angle difference after linear scaling
S = math.sqrt(b / a)
t1 = S * math.sqrt(r1)
t2 = S * math.sqrt(r2)
dtheta = abs(math.atan(t2) - math.atan(t1))
# Enforce non-trivial angular span
if dtheta < 0.15:
    return (False, None)
# Area of annular sector in (w,z): 0.5 * (c2 - c1) * dtheta
# Scale back to (u,v) by dividing by sqrt(a*b)
area = 0.5 * (c2 - c1) * dtheta / math.sqrt(a * b)
ans = int(math.floor(area + 1e-12))
